const knownAreas = [
  { keywords: ["orangi"], lat: 24.9556, lng: 66.9878 },
  { keywords: ["nazimabad", "board office", "lasbela", "numaish", "tariq road", "sadar", "saddar"], lat: 24.9019, lng: 67.0378 },
  { keywords: ["gulshan", "nagan", "north nazimabad", "hamdard", "millennium mall", "national stadium"], lat: 24.9297, lng: 67.0862 },
  { keywords: ["hub dam", "hub"], lat: 25.2450, lng: 67.0500 },
  { keywords: ["malir", "maymar", "maymaar"], lat: 24.8969, lng: 67.2073 },
  { keywords: ["lalzar"], lat: 24.8800, lng: 67.1500 },
  { keywords: ["north karachi"], lat: 24.9700, lng: 67.0500 },
  { keywords: ["saima villas"], lat: 24.9350, lng: 67.1150 },
  { keywords: ["shahre faisal", "defence", "phase 6", "dha"], lat: 24.8138, lng: 67.0611 },
  { keywords: ["site", "super highway"], lat: 24.9100, lng: 67.0700 },
  { keywords: ["university road"], lat: 24.9370, lng: 67.1130 },
  { keywords: ["up more"], lat: 24.9420, lng: 67.1180 },
  { keywords: ["clifton"], lat: 24.8138, lng: 67.0300 },
  { keywords: ["highway"], lat: 24.9200, lng: 67.0900 },
  { keywords: ["karachi"], lat: 24.8607, lng: 67.0011 }
];

function getCoords(text) {
  const lower = (text || "").toLowerCase();
  for (const area of knownAreas) {
    if (area.keywords.some(k => lower.includes(k))) {
      return { lat: area.lat, lng: area.lng };
    }
  }
  // Koi match nahi mila — Karachi ke andar random point, taake pin dikhe blank se behtar
  return {
    lat: 24.8607 + (Math.random() - 0.5) * 0.08,
    lng: 67.0011 + (Math.random() - 0.5) * 0.08
  };
}

const items = $input.all();

const results = items.map(item => {
  const row = item.json;
  const reportCount = parseInt(row.report_count) || 0;
  const avgRating = parseFloat(row.avg_rating) || 3;
  const riskLevel = row.most_common_risk || "medium";

  let score = Math.round((avgRating / 5) * 100);
  if (riskLevel === "high") score = Math.max(0, score - 15);
  if (riskLevel === "low") score = Math.min(100, score + 10);

  const finalRiskLevel = score >= 70 ? "low" : score >= 40 ? "medium" : "high";
  const insufficientData = reportCount < 2;
  const coords = getCoords(row.location_text);

  return {
    json: {
      location_text: row.location_text,
      report_count: reportCount,
      safety_score: score,
      risk_level: finalRiskLevel,
      insufficient_data: insufficientData,
      lat: coords.lat,
      lng: coords.lng
    }
  };
});

return results;
